import React, { useState, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { motion, AnimatePresence } from 'motion/react';
import { 
  SectionLabel, 
  PillButton, 
  FieldDropdown, 
  SegmentedToggle,
} from './components/Primitives';
import { ComparisonSlider } from './components/ComparisonSlider';
import { HistoryGallery } from './components/HistoryGallery';
import { LoadingOverlay } from './components/LoadingOverlay';
import { SketchCanvas, STENCILS } from './components/SketchCanvas';
import { MartianScene } from './types';

type ToolMode = 'select' | 'pencil' | 'brush';

export default function App() {
  const [sketchBase64, setSketchBase64] = useState<string | null>(null);
  const [result, setResult] = useState<MartianScene | null>(null);
  const [history, setHistory] = useState<MartianScene[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [mood, setMood] = useState('Cinematic Red');
  const [activeTool, setActiveTool] = useState<ToolMode>('select');
  const [error, setError] = useState<string | null>(null);

  const canvasRef = useRef<{ 
    addStencil: (type: string) => void; 
    getBase64: () => string; 
    clear: () => void;
    setDrawingMode: (mode: ToolMode) => void;
  }>(null);

  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', sans-serif; letter-spacing: 0.1px; color: white; overflow: hidden; }
      .no-scrollbar::-webkit-scrollbar { display: none; }
      .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleToolChange = (mode: string) => {
    const m = mode as ToolMode;
    setActiveTool(m);
    canvasRef.current?.setDrawingMode(m);
  };

  const handleExecute = async () => {
    if (!canvasRef.current) return;
    const base64 = canvasRef.current.getBase64();
    setIsGenerating(true);
    setError(null);

    try {
      const uploaded = await Flow.upload({
        base64,
        mimeType: 'image/png',
        name: 'Martian Blueprint'
      });

      const prompt = `A cinematic 8k architectural simulation of a Martian colony structure on the red planet. 
        Theme: ${mood}. 
        Atmosphere: Volumetric dust, solar lens flares, sharp technical details.
        The structural layout is strictly based on the provided architectural blueprint sketch.
        Composition: High angle drone shot, dramatic shadows.`;

      const response = await Flow.generate.image({
        prompt,
        referenceImageMediaIds: [uploaded.mediaId],
        modelDisplayName: '🍌 Nano Banana Pro',
        aspectRatio: '16:9'
      });

      const newResult: MartianScene = {
        id: Date.now().toString(),
        sketchBase64: `data:image/png;base64,${base64}`,
        resultBase64: `data:${response.mimeType};base64,${response.base64}`,
        rawResultBase64: response.base64,
        mimeType: response.mimeType,
        params: { mood },
        timestamp: new Date().toLocaleTimeString()
      };

      setResult(newResult);
      setHistory(prev => [newResult, ...prev]);
    } catch (err: any) {
      setError(err.message?.includes('UNSAFE') ? 'Composition rejected by simulation safety protocols.' : 'Atmospheric synthesis failed. Try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      {/* Left Pane: Toolset & Library */}
      <div className="relative border-r border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between px-[10px] py-[12px] w-[300px] h-full shrink-0 z-20 bg-[#0e0e0e]">
        <div className="flex flex-col gap-[24px] items-start w-full overflow-y-auto no-scrollbar pb-6">

          <div className="flex flex-col gap-3 items-start w-full">
            <SectionLabel>Drafting Mode</SectionLabel>
            <SegmentedToggle 
              value={activeTool}
              onChange={handleToolChange}
              items={[
                { value: 'select', label: 'Select', icon: <span className="material-symbols-outlined text-[18px]">near_me</span> },
                { value: 'pencil', label: 'Pencil', icon: <span className="material-symbols-outlined text-[18px]">edit</span> },
                { value: 'brush', label: 'Brush', icon: <span className="material-symbols-outlined text-[18px]">brush</span> },
              ]}
            />
          </div>

          <div className="flex flex-col gap-3 items-start w-full">
            <SectionLabel>Structure Library</SectionLabel>
            <div className="grid grid-cols-2 gap-1.5 w-full">
              {STENCILS.map(s => (
                <button 
                  key={s.id}
                  onClick={() => {
                    setActiveTool('select');
                    canvasRef.current?.addStencil(s.type);
                  }}
                  className="group flex flex-col items-center gap-1.5 p-2 rounded-xl border border-[#595959] bg-white/5 hover:bg-white/10 hover:border-white/40 transition-all active:scale-95"
                >
                  <span className="material-symbols-outlined text-white/40 group-hover:text-white transition-colors text-[22px]">{s.icon}</span>
                  <span className="text-[9px] text-white/30 uppercase font-bold tracking-tight text-center leading-tight group-hover:text-white/70">{s.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-3 items-start w-full">
            <SectionLabel>Atmosphere</SectionLabel>
            <FieldDropdown 
              label="Visual Mood" 
              value={mood}
              options={['Cinematic Red', 'Golden Dust', 'Nocturnal Blue', 'Scientific White', 'Terraformed Green']}
              onChange={setMood}
              className="w-full"
            />
          </div>

          <div className="flex flex-col gap-2 items-start w-full border-t border-white/5 pt-4">
            <SectionLabel>Draft Tools</SectionLabel>
            <PillButton variant="outline" onClick={() => canvasRef.current?.clear()} icon={<span className="material-symbols-outlined text-[18px]">delete</span>}>Clear All</PillButton>
          </div>
        </div>

        <div className="flex flex-col gap-[5px] items-start w-full pt-2">
          {error && <p className="text-[10px] text-red-400 px-2 pb-2 leading-tight">{error}</p>}
          <PillButton 
            variant="solid" 
            onClick={handleExecute}
            disabled={isGenerating}
            icon={<span className="material-symbols-outlined text-[18px]">rocket_launch</span>}
          >
            {isGenerating ? 'Synthesizing...' : 'Execute Build'}
          </PillButton>
        </div>
      </div>

      {/* Center Display Area */}
      <div className="flex-1 relative flex flex-col h-full overflow-hidden bg-[#0a0a0a]">
        <div className="flex-1 relative flex items-center justify-center p-4">
          <AnimatePresence mode="wait">
            {result ? (
              <motion.div 
                key="result"
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                className="w-full h-full max-w-5xl aspect-video rounded-2xl overflow-hidden shadow-2xl border border-white/10 relative bg-[#0e0e0e]"
              >
                <ComparisonSlider before={result.sketchBase64} after={result.resultBase64} />
                <button 
                  onClick={() => setResult(null)}
                  className="absolute top-4 left-4 h-10 px-4 rounded-full bg-black/60 backdrop-blur-md flex items-center gap-2 hover:bg-white/10 transition-colors border border-white/10 text-xs font-bold text-white z-50 shadow-xl"
                >
                  <span className="material-symbols-outlined text-[18px]">draw</span>
                  Modify Drafting
                </button>
              </motion.div>
            ) : (
              <motion.div 
                key="canvas"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="w-full h-full flex items-center justify-center"
              >
                <SketchCanvas ref={canvasRef} />
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* History Gallery */}
        <HistoryGallery history={history} onSelect={setResult} currentId={result?.id} />
      </div>

      {isGenerating && <LoadingOverlay message="Synthesizing Colony Structures..." />}
    </div>
  );
}

export interface MartianScene {
  id: string;
  sketchBase64: string;
  resultBase64: string;
  rawResultBase64: string;
  mimeType: string;
  params: {
    mood: string;
  };
  timestamp: string;
}

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => { document.removeEventListener('mousedown', listener); document.removeEventListener('touchstart', listener); };
  }, [ref, handler]);
}

export const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  onChange: (val: string) => void; className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useOnClickOutside(ref, () => setIsOpen(false));

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none bg-black/20">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate pr-2">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const RangeSlider: React.FC<{
  label: string; value: number; min: number; max: number;
  step?: number; formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))} />
    </div>
  </div>
);

export const SegmentedToggle: React.FC<{
  value: string; items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1 h-[34px] px-3 py-2 rounded-xl text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

export const TextInput: React.FC<{
  value: string; onChange: (val: string) => void; placeholder?: string;
}> = ({ value, onChange, placeholder }) => (
  <textarea value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder}
    className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[60px] px-3 py-2.5 resize-none bg-black/20 text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.4)] tracking-[0.1px] focus:outline-none transition-colors" />
);

import React, { useState, useRef, useEffect } from 'react';
import { motion, useMotionValue, useTransform } from 'motion/react';

interface ComparisonSliderProps {
  before: string;
  after: string;
}

export const ComparisonSlider: React.FC<ComparisonSliderProps> = ({ before, after }) => {
  const [sliderPos, setSliderPos] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const position = ((x - rect.left) / rect.width) * 100;
    setSliderPos(Math.min(Math.max(position, 0), 100));
  };

  return (
    <div 
      ref={containerRef}
      className="relative w-full h-full cursor-col-resize select-none overflow-hidden"
      onMouseMove={handleMove}
      onTouchMove={handleMove}
    >
      {/* Before Image (Draft) */}
      <div className="absolute inset-0">
        <img src={before} className="w-full h-full object-cover grayscale opacity-60" alt="Draft" />
        <div className="absolute bottom-4 left-4 bg-black/40 backdrop-blur-md px-2 py-1 rounded text-[10px] uppercase tracking-widest font-bold border border-white/10">Sketch</div>
      </div>

      {/* After Image (Render) */}
      <div 
        className="absolute inset-0 overflow-hidden"
        style={{ width: `${sliderPos}%` }}
      >
        <img 
          src={after} 
          className="w-full h-full object-cover" 
          style={{ width: `${100 / (sliderPos / 100)}%` }}
          alt="Martian Reality" 
        />
        <div className="absolute bottom-4 right-4 bg-white/90 px-2 py-1 rounded text-black text-[10px] uppercase tracking-widest font-bold">Martian View</div>
      </div>

      {/* Handle */}
      <div 
        className="absolute top-0 bottom-0 w-0.5 bg-white shadow-[0_0_10px_rgba(255,255,255,0.5)] z-10"
        style={{ left: `${sliderPos}%` }}
      >
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-white flex items-center justify-center shadow-lg">
          <span className="material-symbols-outlined text-black text-[18px]">unfold_more</span>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { motion } from 'motion/react';
import { MartianScene } from '../types';

interface HistoryGalleryProps {
  history: MartianScene[];
  onSelect: (scene: MartianScene) => void;
  currentId?: string;
