import React, { useRef, useState, useEffect, useImperativeHandle, forwardRef } from 'react';
import * as fabric from 'fabric';

export const STENCILS = [
  { id: 'hub', name: 'Command Hub', type: 'hub', icon: 'hub' },
  { id: 'pod', name: 'Modular Unit', type: 'rect_rounded', icon: 'rectangle' },
  { id: 'corridor', name: 'Access Link', type: 'rect', icon: 'straighten' },
  { id: 'ring', name: 'Foundation Ring', type: 'ring', icon: 'radio_button_unchecked' },
  { id: 'hex', name: 'Hex Cell', type: 'hexagon', icon: 'hexagon' },
  { id: 'pent', name: 'Pentagon Base', type: 'pentagon', icon: 'pentagon' },
  { id: 'octa', name: 'Octagon Dome', type: 'octagon', icon: 'pentagon' },
  { id: 'deca', name: 'Decagon Plaza', type: 'decagon', icon: 'pentagon' },
  { id: 'spiro', name: 'Spirograph', type: 'spirograph', icon: 'auto_awesome' },
  { id: 'solar', name: 'Solar Array', type: 'solar', icon: 'grid_view' },
];

const CANVAS_BG = '#150a08';
const GRID_COLOR = 'rgba(255, 255, 255, 0.05)';

export const SketchCanvas = forwardRef((props, ref) => {
  const canvasElementRef = useRef<HTMLCanvasElement>(null);
  const fabricRef = useRef<fabric.Canvas | null>(null);

  useEffect(() => {
    if (!canvasElementRef.current) return;

    const canvas = new fabric.Canvas(canvasElementRef.current, {
      width: 1200,
      height: 675,
      backgroundColor: CANVAS_BG,
    });

    fabricRef.current = canvas;

    // Grid lines for architectural feel
    for (let i = 0; i < 1200; i += 40) {
      canvas.add(new fabric.Line([i, 0, i, 675], { stroke: GRID_COLOR, selectable: false, evented: false }));
    }
    for (let i = 0; i < 675; i += 40) {
      canvas.add(new fabric.Line([0, i, 1200, i], { stroke: GRID_COLOR, selectable: false, evented: false }));
    }

    return () => { canvas.dispose(); };
  }, []);

  const createPolygon = (sides: number, radius: number, options: any) => {
    const points = [];
    for (let i = 0; i < sides; i++) {
      const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
      points.push({ x: radius * Math.cos(angle), y: radius * Math.sin(angle) });
    }
    return new fabric.Polygon(points, options);
  };

  const createSpirograph = (radius: number, options: any) => {
    const group = new fabric.Group([], options);
    // Create a series of overlapping rotated ellipses to simulate a spirograph
    for (let i = 0; i < 8; i++) {
      const ellipse = new fabric.Ellipse({
        rx: radius,
        ry: radius / 2.5,
        fill: 'transparent',
        stroke: '#ffffff',
        strokeWidth: 1,
        angle: (i * 180) / 8,
        left: options.left,
        top: options.top,
        originX: 'center',
        originY: 'center',
      });
      group.add(ellipse);
    }
    return group;
  };

  useImperativeHandle(ref, () => ({
    setDrawingMode: (mode: 'pencil' | 'brush' | 'select') => {
      if (!fabricRef.current) return;
      const canvas = fabricRef.current;

      if (mode === 'select') {
        canvas.isDrawingMode = false;
      } else {
        canvas.isDrawingMode = true;
        const brush = new fabric.PencilBrush(canvas);
        brush.color = '#ffffff';
        brush.width = mode === 'brush' ? 8 : 2;
        canvas.freeDrawingBrush = brush;
      }
    },
    addStencil: (type: string) => {
      if (!fabricRef.current) return;
      const canvas = fabricRef.current;
      // Disable drawing mode when adding a stencil
      canvas.isDrawingMode = false;

      let obj: fabric.Object;
      const common = {
        left: 600,
        top: 337,
        fill: 'transparent',
        stroke: '#ffffff',
        strokeWidth: 2,
        originX: 'center' as const,
        originY: 'center' as const,
      };

      switch (type) {
        case 'hub':
          const circle = new fabric.Circle({ ...common, radius: 40 });
          const line1 = new fabric.Rect({ ...common, width: 120, height: 2, fill: '#ffffff', stroke: 'none' });
          const line2 = new fabric.Rect({ ...common, width: 2, height: 120, fill: '#ffffff', stroke: 'none' });
          obj = new fabric.Group([circle, line1, line2], { ...common });
          break;
        case 'rect_rounded':
          obj = new fabric.Rect({ ...common, width: 80, height: 80, rx: 12, ry: 12 });
          break;
        case 'rect':
          obj = new fabric.Rect({ ...common, width: 150, height: 20 });
          break;
        case 'ring':
          obj = new fabric.Circle({ ...common, radius: 100 });
          break;
        case 'hexagon':
          obj = createPolygon(6, 50, common);
          break;
        case 'pentagon':
          obj = createPolygon(5, 55, common);
          break;
        case 'octagon':
          obj = createPolygon(8, 55, common);
          break;
        case 'decagon':
          obj = createPolygon(10, 60, common);
          break;
        case 'spirograph':
          obj = createSpirograph(100, common);
          break;
        case 'solar':
          obj = new fabric.Rect({ ...common, width: 60, height: 60, strokeDashArray: [5, 5] });
          break;
        default:
          obj = new fabric.Circle({ ...common, radius: 50 });
      }

      canvas.add(obj);
      canvas.setActiveObject(obj);
      canvas.requestRenderAll();
    },
    getBase64: () => {
      return fabricRef.current?.toDataURL({ format: 'png', multiplier: 1.5 }).split(',')[1] || '';
    },
    clear: () => {
      if (!fabricRef.current) return;
      // Only clear user objects, keep grid
      fabricRef.current.getObjects().forEach(o => {
        if (o.selectable) fabricRef.current?.remove(o);
        if (o.type === 'path') fabricRef.current?.remove(o); // Freehand paths
      });
      fabricRef.current.requestRenderAll();
    }
  }));

  return (
    <div className="w-full max-w-5xl aspect-video bg-[#0a0a0a] rounded-xl border border-white/5 shadow-2xl overflow-hidden flex items-center justify-center">
      <canvas ref={canvasElementRef} />
    </div>
  );
});
